<?php
foreach(['APP_ENV'=>'testing','APP_CONFIG_CACHE'=>'/tmp/cash-sales-test.php','DB_CONNECTION'=>'sqlite','DB_DATABASE'=>':memory:','CACHE_STORE'=>'array','SESSION_DRIVER'=>'array','LOG_CHANNEL'=>'stderr'] as $k=>$v){putenv("$k=$v");$_ENV[$k]=$v;$_SERVER[$k]=$v;}
require dirname(__DIR__,2).'/vendor/autoload.php';$app=require dirname(__DIR__,2).'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\{DB,Schema};use App\Agent\Tools\{HandoffToHumanTool,ToolContext};use App\Agent\Runtime\{EvidenceReview,SocialReply};use App\Models\WhatsappConversation;
if(DB::connection()->getDriverName()!=='sqlite'||config('database.connections.sqlite.database')!==':memory:')throw new RuntimeException('Unsafe DB');
Schema::create('whatsapp_conversations',function($t){$t->id();$t->string('phone')->nullable();$t->string('status');$t->text('last_topic')->nullable();$t->json('state')->nullable();$t->timestamps();});
Schema::create('whatsapp_messages',function($t){$t->id();$t->integer('whatsapp_conversation_id');$t->integer('turn_id')->nullable();$t->string('sender_type');$t->string('direction');$t->text('text')->nullable();$t->text('transcript')->nullable();$t->timestamps();});
Schema::create('machines',function($t){$t->id();$t->string('name');$t->boolean('is_active')->default(true);$t->string('type')->default('normal');$t->decimal('cash_price');$t->decimal('new_price')->nullable();});
Schema::create('handoffs',function($t){$t->id();$t->integer('conversation_id');$t->string('reason');$t->text('note');$t->string('source');$t->dateTime('opened_at');$t->dateTime('closed_at')->nullable();$t->timestamps();});
Schema::create('staff',function($t){$t->id();$t->boolean('is_admin')->default(false);$t->boolean('is_super_admin')->default(false);});
DB::table('machines')->insert(['id'=>26,'name'=>'VLM 200','cash_price'=>73000]);
$c=WhatsappConversation::create(['phone'=>'201012345678','status'=>'open']);
$ctx=new ToolContext(1,$c->id,null,7,1,new App\Agent\Runtime\TurnResultBuilder());
$review=new class extends EvidenceReview {public bool $allow=false;public function judge(string $task,array $data):bool{return $this->allow && $task==='cash_purchase_confirmed';}};
$app->instance(EvidenceReview::class,$review);
$app->instance(App\Agent\Runtime\CatalogMentions::class,new class extends App\Agent\Runtime\CatalogMentions {public function fullNames(string $text):array{return str_contains($text,'vlm')||str_contains($text,'VLM')?[26]:[];}});
config(['agent.cash.sales_handoff'=>true,'agent.handoff.customer_only'=>true,'agent.cash.purchase_handoff_message'=>'approved cash handoff','agent.cash.purchase_handoff_topic'=>'cash purchase']);
$tool=app(HandoffToHumanTool::class);$args=['reason'=>'cash_purchase_confirmed','note'=>'purchase','motorcycle_id'=>26,'request_quote'=>'عايز اشتريها كاش دلوقتي'];
$n=0;$ok=function($v,$name)use(&$n){if(!$v)throw new RuntimeException($name);echo "PASS $name\n";$n++;};
$run=fn()=> $tool->execute($args,$ctx)->toArray();
$ok(in_array('cash_purchase_confirmed',$tool->inputSchema()['properties']['reason']['enum'],true),'cash purchase reason declared');
$ok(($run()['error']['code']??'')==='CURRENT_PURCHASE_CONFIRMATION_REQUIRED','invented customer quote blocked');
DB::table('whatsapp_messages')->insert(['whatsapp_conversation_id'=>$c->id,'turn_id'=>7,'sender_type'=>'customer','direction'=>'incoming','text'=>$args['request_quote']]);
$ok(($run()['error']['code']??'')==='CASH_PRICE_MUST_BE_QUOTED_FIRST','no handoff before a price was quoted');
DB::table('whatsapp_messages')->delete();
DB::table('whatsapp_messages')->insert(['whatsapp_conversation_id'=>$c->id,'turn_id'=>6,'sender_type'=>'bot','direction'=>'outgoing','text'=>'بينيلي VLM 200 سعرها كاش 73,000 جنيه']);
DB::table('whatsapp_messages')->insert(['whatsapp_conversation_id'=>$c->id,'turn_id'=>7,'sender_type'=>'customer','direction'=>'incoming','text'=>$args['request_quote']]);
$ok(($run()['error']['code']??'')==='CASH_PURCHASE_NOT_CONFIRMED','unconfirmed intent cannot transfer');
$ok(DB::table('handoffs')->count()===0,'rejected confirmation does not change conversation');
$review->allow=true;$result=$run();
$ok(($result['data']['handed_off']??false)===true,'confirmed purchase transfers without any inventory table');
$ok($result['data']['customer_message']==='approved cash handoff','handoff notice comes from dashboard');
$ok($c->fresh()->status==='awaiting_agent','purchase enters waiting-for-staff queue');
$ok(!App\Domain\Handoff\HandoffService::botKeepsAnswering($c->fresh()),'bot stops after cash transfer');
$run();$ok(DB::table('handoffs')->count()===1,'purchase transfer is idempotent');
$ok(DB::table('handoffs')->value('reason')==='cash_purchase_confirmed','cash purchase has its own reason');
config(['agent.cash.sales_handoff'=>false]);$ok(($run()['error']['code']??'')==='CASH_SALES_DISABLED','disabled route cannot be invoked');
config(['agent.social.replies'=>json_encode(['تمام'=>'العفو','مساء الخير'=>'مساء النور','👍'=>''],JSON_UNESCAPED_UNICODE)]);
$social=new SocialReply;
$ok($social->for('تمام')['messages']===['العفو'],'acknowledgment uses approved memory response');
$ok($social->for('مساء الخير')['messages']===['مساء النور'],'greeting bypasses business-fact review safely');
$ok(($social->for('👍')['no_reply']??false)===true,'reaction can be silent');
$ok($social->for('تمام طلبي وصل لفين')===null,'status question is never mistaken for thanks');
$ok($social->for('عايز VLM كاش')===null,'business question still uses agent tools');
echo "$n passed\n";
